INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('2','ANNUAL FUNCTION','<p>Dear Parents, </p><p><br></p><p>????Kindly give the names of the interested students participating in Annual Day by 25 November 2023 (Saturday)</p><p><br></p><p>????Later on names will not be added.</p><p><br></p><p>????Annual day amount is 800₹.</p><p><br></p><p>????Tentative date for the function will be 22nd or 23rd Dec 2023.</p><p><br></p><p>????Amount once paid will not be refunded and names once given to the class teacher will not be cancelled. </p><p><br></p><p>Thanks and Regards</p><p>P.P.G.M.I.S</p>','2','2023-11-20','2023-11-20 13:47:00','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('3','NOTICE FOR GRADE 1 TO GRADE 7','<p>Dear Parents,</p><p><br></p><p>The students those who are participating in the Exhibition will come to School tomorrow with their model, charts, exhibits etc. Timing will be 10 am to 12 pm.</p><p>Kindly use the Janta Vidyalaya School gate for entry and exit.</p><p><br></p><p>All the non-participants will have holiday tomorrow.</p><p><br></p><p>Thanks and Regards</p>','2','2023-11-23','2023-11-23 17:53:32','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('4','FOR NURSARY, PREP 1 A & B, PREP 2 A & B','<p> Dear Parents, </p><p><br></p><p>Tomorrow there will be holiday for Prep section due to preparation of exibit .</p><p><br></p><p>Regards</p><p>P.P.G.M.I.S.</p>','2','2023-11-23','2023-11-23 17:55:44','1','1',NULL,NULL);
