INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('17','Class Test - Grade 1 to Grade 9','<p><br></p><p>Subject: Class Test Schedule for Classes I to IX</p><p><br></p><p>Dear Parents,</p><p><br></p><p>Please be informed that class tests for Classes I to IX will be conducted as per the following schedule:</p><p><span xss=removed>•22ndJuly – English, Marathi</span></p><p><span xss=removed>•23rd July – Mathematics, Hindi</span></p><p><span xss=removed>•24th July – Science/EVS, Sanskrit</span></p><p><span xss=removed>•25th July – Social Sciences</span></p><p><br></p><p>These class tests are compulsory and form an integral part of the internal evaluation. Parents are requested to ensure that their wards attend the tests without fail.</p><p><br></p><p>Regards,</p><p>PPGMIS, Khopoli</p>','3','2025-07-21','2025-07-21 09:27:28','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('18','Periodic Test 1 2025-206-Ranker Badges','<p>Dear Parents,</p><p><br></p><p>We are pleased to inform you that badges were awarded to all rank holders for their achievements in Periodic Test 1, held in June.</p><p><br></p><p>We kindly request that these badges be returned to the respective class teachers by Friday, 25th July 2025. In case a badge is lost, misplaced, or damaged, a replacement fine of ₹100 will be applicable.</p><p><br></p><p>We appreciate your support and cooperation in maintaining the value and integrity of these recognitions.</p><p><br></p><p>Warm regards,</p><p>Team PPGMIS</p>','3','2025-07-21','2025-07-21 14:16:44','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('19','Nursery TO Grade 9','<p>Dear Parents,</p>Due to heavy rainfall,the school will remain closed today,i.e.,25th July 2025.<p><br></p><p>Stay safe and take care.</p><p><br></p><p>Regards,</p><p>PPGMIS,Khopoli.</p>','3','2025-07-25','2025-07-25 08:21:16','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('20','Holiday','<p>Dear Parents,</p><p><br></p><p>In view of the heavy rainfall forecast by the weather department, the school will remain closed tomorrow, <b>26th July 2025.</b></p><p><br></p><p>The drawing competition has been postponed, and new date will be announced shortly.</p><p><br></p><p><b>For Grades 6 to 9, online classes will be conducted via Zoom.</b></p><p><br></p><p>Stay safe and take care.</p><p><br></p><p>Regards,</p><p>PPGMIS, Khopoli</p>','3','2025-07-25','2025-07-25 21:02:02','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('21','Drawing Competition- Grade 1 to Grade 9','<p>Dear Parents,</p><p>We believe that art is a powerful tool for children to express themselves, build confidence, and explore their creativity. With this in mind, we are excited to announce an inter-class Drawing Competition will be held <b>tomorrow, i.e. 30/07/25</b> . </p><p><b>for  Grade  1 to 9</b></p><p> Important Instructions for Students:</p><p>- Prepare for both the topics listed below.</p><p>- One topic will be randomly assigned on the spot.</p><p>- Bring all necessary materials from home.</p><p>- Drawing Sheet will be provided by School.</p><p><br></p><p>We look forward to seeing the creative expressions of our students!</p><p><br></p><p>Thanks and Regards,</p><p>Principal, </p><p>PPGMIS, Khopoli.</p>','3','2025-07-29','2025-07-29 13:54:59','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('22','Nursery to Prep 2','<p>Dear Parents,</p><p><b>Market Day Celebration</b></p><p><b>Tomorrow i.e,August 1st</b>, our Pre-Primary students will celebrate Market Day during school hours. We encourage students to dress up as vegetable sellers, adding to the festive spirit!</p><p><br></p><p>Looking forward to a fun-filled day!</p><p><br></p><p>Best regards,</p><p>Principal </p><p>PPGMIS</p>','3','2025-07-31','2025-07-31 14:38:00','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('30','Nursery to Prep 2','<p>Dear Parents,</p><p>Greetings!</p><p>We are excited to announce the<b> Rangotsav Celebration National Level Art Competition for Nursery to Prep 2</b> students . The competition features four exciting categories:-</p><p><br></p><p>1] Colouring Competition</p><p>2] Handwriting Competition</p><p>3] Collage Competition</p><p>4] Thumb printing competition</p><p><br></p><p>Students interested in participating can register by paying <b>₹50</b> per competition to their class teacher <b>before 8th August</b>. The competition will be held in the <b>third week of August in school.</b></p><p><br></p><p>Regards,</p><p>Principal, PPGMIS, Khopoli.</p>','3','2025-08-03','2025-08-03 19:10:23','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('31','Grade 1 to Grade 9','<p>Dear Parents,</p><p>Greetings!</p><p>We are excited to announce the <b>Rangotsav Celebration National Level Art Competition</b> for students from <b>Grade 1 to Grade 9</b>. The competition features Ten exciting categories: </p><p><br></p><p>1) Colouring Competition</p><p>2) Handwriting Competition </p><p>3) Collage Competition</p><p>4) Mask Making Competition </p><p>5) Cartoon Drawing Competition</p><p>6) Greeting Card Making Competition</p><p>7) Sketching Competition</p><p>8) Tattoo making</p><p>9) Caricature Competition</p><p>10) Finger and  thumb painting competition </p><p><br></p><p>Students interested in participating can register by paying <b>₹50</b> per competition to their class teacher <b>before 8th August</b>. The competition will be held in the <b>third week of August in school</b>.</p><p><br></p><p>Regards,</p><p>Principal, </p><p>PPGMIS, Khopoli.</p>','3','2025-08-03','2025-08-03 19:12:54','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('32','Nursery to Grade9','<p>Notice for Parents</p><p><br></p><p>Dear Parents,</p><p><br></p><p>As you know, Raksha Bandhan is just around the corner! On this occasion, <b>Shalom students (Special School)</b> from Khopoli will be visiting our school <b>tomorrow i.e. 06th August 2025 </b>to sell Rakhi\'s. The Rakhi\'s are available in a range of prices, <b>from ₹2 to ₹50.</b></p><p><br></p><p>To participate, kindly send the amount with your <b>ward and inform the Class Teacher accordingly.</b></p><p><br></p><p>Thank you for your cooperation!</p>','3','2025-08-05','2025-08-05 20:32:33','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('33','Pre primary section','<p>Dear Parents,</p><p><br></p><p>We are pleased to inform you that the Ganapati vacation for our Pre-Primary students will begin from tomorrow, 26th August, and will continue till 2nd September.</p><p><br></p><p>The school will <b>reopen on 3rd September.</b></p><p><br></p><p>Wishing you and your family a joyful and blessed festive break! ✨</p><p><br></p><p>Warm regards,</p><p>PPGMIS</p>','3','2025-08-25','2025-08-25 15:38:37','4','2',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('35','Nursery to Prep 2','<p>Dear Parents,</p><p><br></p><p>Please note that the Ganpati Holiday Homework has been sent on the school app. Going forward, kindly check the app daily for:</p><p><br></p><p>- Everyday homework</p><p>- CCA competition updates</p><p>- Holiday notifications</p><p><br></p><p>All updates will be shared exclusively on the app, and no further notifications will be sent on WhatsApp.</p><p><br></p><p>For best viewing experience and to access full messages, kindly open the app through Google Chrome.</p>','3','2025-08-26','2025-08-26 14:00:48','4','2',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('36','CCA Drawing Competition (Nursery to Prep 2)','<p>Dear Parents,</p><p>Greetings!</p><p>We believe that art is a powerful tool for children to express themselves, build confidence, and explore their creativity. With this in mind, we are excited to announce an inter-class Drawing Competition for the Pre-Primary section <b>(Nursery to Prep 2), scheduled for September 9th, 2025.</b></p><p><b>Important Instructions for Students:</b></p><p>- Prepare for both topics listed below.</p><p>- One topic will be randomly assigned on the spot.</p><p>- Bring all necessary materials from home.</p><p>- Drawing sheets will be provided by the school.</p><p><br></p><p>Please find the topics in the attached file sent on the <b>Academic section under Assignments.</b></p><p><br></p><p>We look forward to seeing the creative expressions of our students!</p><p><br></p><p>Thanks and Regards,</p><p>Principal</p><p>PPGMIS</p><p>Khopoli</p>','3','2025-08-26','2025-08-26 14:36:48','4','2',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('37','Grade 1 to 9 -Ganapati Vacation','<p>Dear Parents,</p><p><br></p><p>We are pleased to inform you that the <b>Ganapati vacation </b>for <b>Grade 1 to 9 </b>students will begin from tomorrow, <b>27th August 2025 and will continue till 2nd September 2025</b>.</p><p><br></p><p>The school will <b>reopen on Wednesday, 3rd September 2025.</b></p><p><br></p><p>Wishing you and your family a joyful and blessed festive break! ????</p><p><br></p><p>Warm regards,</p><p>PPGMIS</p>','3','2025-08-26','2025-08-26 15:04:30','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('38','Nursery to Grade 9-School Reopen','<p>Dear Parents,</p><p><br></p><p>We hope you had a joyful Ganapati Vacation. Kindly note that regular school will resume from <b>tomorrow, 03/09/2025</b> <b>(Wednesday)</b>.</p><p><br></p><p>Thank you</p><p>PPGMIS</p>','3','2025-09-02','2025-09-02 12:23:28','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('39','Nursery to Grade 9','<p>Dear Parents,</p><p><br></p><p>This is to inform you that the school will remain <b>closed on Friday, 5th September 2025 (Eid-e-Milad) and Saturday, 6th September 2025 (Anant Chaturthi)</b>.</p><p>We are also pleased to inform you that <b>Teachers’ Day and Onam celebrations</b> will be held on <b>Friday, 12th September 2025</b>.</p><p><br></p><p>Thank you.</p><p>Principal</p><p>PPGMIS</p>','3','2025-09-04','2025-09-04 13:22:12','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('40','Preprimary section CCA Reminder','<p>*Notice: Upcoming Recitation Competition*</p><p><br></p><p>Dear Parents,</p><p>Greetings!</p><p><br></p><p>Renowned educator Wei Shusheng once said, “The sense of language has also been strengthened by reciting more.” Recitation is a powerful way to enhance language skills and develop an appreciation for literature. It also provides a platform for students to showcase their talent and confidence.</p><p><br></p><p>In light of this, the school is pleased to announce <b>tomorrow there will be English recitation competitions:</b></p><p><br></p><p>Note:</p><p>Criteria -Use of props, Memory,  Voice Modulation, Presentation.</p><p><br></p><p>Please refer to the attached PDF in the app for the respective topic.</p><p><br></p><p>Best wishes to all participants!</p><p><br></p><p><br></p><p>Regards,</p><p>Principal, </p><p>PPGMIS, </p><p>Khopoli.</p>','3','2025-09-10','2025-09-10 15:36:00','36','2',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('41','Nursery to Prep 2','<p>Dear Parents,</p><p><br></p><p>As informed earlier, we are celebrating Teachers’ Day and Onam on Friday, 12th September 2025.</p><p>On this day, the school will <b>disperse at 11:30 a.m</b>. Parents are kindly requested to make arrangements to pick up their wards on time.</p><p><br></p><p>Thank you</p>','3','2025-09-10','2025-09-10 18:32:34','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('42','Grade 1 to Grade 9','<p>Dear Parents,</p><p><br></p><p>As informed earlier, we are celebrating Teachers’ Day and Onam on Friday, 12th September 2025.</p><p>On this day, the school will <b>disperse at 11:15 a.m</b>. Parents are kindly requested to make arrangements to pick up their wards on time.</p><p><br></p><p>Thank you.</p>','3','2025-09-10','2025-09-10 18:33:51','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('43','Grade 1 to Grade 9','<p><b>Half Yearly Exam Schedule</b></p><p>Dear Parents,</p><p>As you know, we are starting our Half Yearly Examination. Kindly note the following important instructions:</p><p><b>1️⃣ Wednesday, 17/09/2025</b></p><p>Grade 1 to 9 → School will leave at 10:45 am.</p><p><b>2️⃣ Thursday, 18/09/2025</b></p><p>Grade 3 to 9 → Study Leave</p><p>Grade 1 & 2 → Half Day School (7:40 am to 10:45 am)</p><p><b>3️⃣ Friday, 19/09/2025</b></p><p>Grade 3 to 9 → Exams as per schedule.</p><p>Grade 1 & 2 → School (7:40 am to 10:45 am)</p><p><br></p><p>So parents please note all the instructions and follow the same.</p><p><br></p><p>Regards </p><p>PPGMIS</p>','3','2025-09-15','2025-09-15 13:48:27','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('44','Nursery to Prep 2','<p>NOTICE</p><p><br></p><p>Subject: Pre-Primary Open Day</p><p><br></p><p>Dear Parents,</p><p><br></p><p>We are pleased to invite you to the Pre-Primary Open Day scheduled for tomorrow, 27th September 2025, from 8:30 AM to 09:30 AM.</p><p><br></p><p>This is a wonderful opportunity for you to observe your child’s learning environment and interact with the teaching staff.</p><p><br></p><p>- Kindly follow the given time strictly.</p><p>- Parents are also requested to clear any pending fees before the end of September 2025.</p><p><br></p><p>We look forward to your presence and active participation.</p><p><b></p><p><b>Venue: Pre-Primary Block</b></p><p><b>Time: 8:30 AM – 09:30 AM</b></p><p><b>Date: 27/09/2025</b></p><p><br></p><p>Regards and Thanks,</p><p>Principal </p><p>PPGMIS.</p>','3','2025-09-26','2025-09-26 13:01:46','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('45','Nursery to Prep 2','<p>Dear Parents,</p><p>We are pleased to inform you that the <b>Bhondla celebration for our Pre-Primary students</b> will be held on <b>Tuesday, 30th September 2025.</b></p><p>Please note the following details:</p><p>-The celebration will take place during regular school hours.</p><p>-It will be a full-day school for all Pre-Primary children.</p><p>-Students are requested to come dressed in colourful traditional attire suitable for the occasion.</p><p>We look forward to a joyful and engaging day of traditional festivities for our little ones!</p><p><br></p><p>Regards and Thanks </p><p>Principal </p><p>PPGMIS.</p>','3','2025-09-29','2025-09-29 13:46:51','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('46','Grade 1 to Grade 9','<p>Dear Parents,</p><p>This is to inform you that the <b>SOF IGKO (International General Knowledge Olympiad)</b> examination is scheduled to be held in the school on <b>Wednesday, 8th October 2025 (i.e., tomorrow)</b> during regular <b>school hours</b>. You are requested to ensure that the participating students come well-prepared for the examination.</p><p><br></p><p>Thank you for your cooperation.</p><p><br></p><p>Regards,</p><p>PPGMIS</p>','3','2025-10-07','2025-10-07 08:13:17','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('47','Grade 1 to Grade 9','<p><b>Notice: Open Day for 1st Semester Examination</b></p><p>Dear Parents,</p><p>You are requested to attend the <b>Open Day for the 1st Semester Examination on Saturday, 11th October 2025, between 8:30 a.m. and 10:00 a.m</b>. Kindly adhere to the given time strictly.</p><p><b>No papers will be shown after 10:00 a.m. under any circumstances.</b></p><p>Parents who wish to pay the school fees are requested to do so<b> on or before 10th October 2025</b> during school hours.</p><p>Please note: <b>Fee collection will not be done on the Open Day i.e. 11th October, 2025</b></p><p>Your cooperation is highly appreciated.</p><p>Warm regards,</p><p>Principal</p><p>PPGMIS, Khopoli</p>','3','2025-10-08','2025-10-08 08:16:14','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('48','Nursery to Prep 2','<p>Dear Parents,</p><p>This is to inform you that those who have not seen the Evaluation papers may come to school on <b>Saturday, 11th October 2025</b>,</p><p>-<b>Time: 9:00 AM to 9:30 AM.</b></p><p>Kindly make use of this opportunity to review your child’s performance.</p><p>Thank you for your cooperation.</p><p><br></p><p>Thanks and regards,</p><p>Principal </p><p>PPGMIS.</p>','3','2025-10-08','2025-10-08 08:18:12','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('49','Nursery to Prep 2','<p>Happy Diwali Dear Parents! </p><p>On the joyful occasion of Diwali, our school has organized a <b>Diya Sale </b></p><p><b>on Saturday, 11th October 2025</b></p><p><b>Time : 9am to 9.30am</b></p><p>The special thing is that each Diya has been lovingly made by our talented students from Grade 1 to 9.</p><p>We request all parents to kindly support and encourage our young creators by purchasing these beautiful Diya\'s.</p><p><b>Price:</b></p><p><b>1 Diya – ₹10</b></p><p><b>1 Dozen – ₹100</b></p><p><b>Please note: Cash payment only (No Google Pay).</b></p><p><br></p><p>Let’s celebrate this Diwali with light, love, and our children’s creativity! ????</p><p>PPGMIS Family.</p>','3','2025-10-10','2025-10-10 13:58:30','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('50','Grade 1 to Grade 9','<p>Happy Diwali Dear Parents</p><p>On the joyful occasion of Diwali, our school has organized a<b> Diya Sale on Saturday, 11th October 2025 </b><b>Timing 8.30am to 10.00am.</b>The special thing is that each Diya has been lovingly made by our talented students from Grade 1 to 9. </p><p>We request all parents to kindly support and encourage our young creators by purchasing these beautiful Diya\'s.</p><p><b>Price:1 Diya – ₹10</b></p><p><b>         1 Dozen – ₹100</b></p><p><b>Please note: Cash payment only (No Google Pay).</b></p><p><br></p><p>Let’s celebrate this Diwali with light, love, and our children’s creativity!</p><p>PPGMIS Family.</p>','3','2025-10-10','2025-10-10 14:05:25','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('51','Prep 1 & Prep 2','<p><b>Lemon Juice Making Activity</b> </p><p> Dear Parents,</p><p>On <b>Thursday, 16th October 2025</b> , we are conducting a Lemon Juice Making Activity.</p><p><b>Students should bring: </b></p><p><b>1 steel glass</b></p><p><b>1 steel spoon</b></p><p><b>(Plastic glass and spoon are not allowed.)</b></p><p><b> Please write your child’s name on the glass and spoon. </b></p><p>Thank you!</p><p><b>Learn this poem for activity </b></p><p>Lemon Juice Poem </p><p>Squeeze lemon… nice and sweet,</p><p>Add some sugar — what a treat!</p><p>Add some salt, just a bit,</p><p>Add some water — mix it, mix it!</p><p>Stir it well, take a sip,</p><p>Yummy juice for every lip!</p><p>Healthy drink, fresh and bright,</p><p>Lemon juice makes us feel right! </p>','3','2025-10-14','2025-10-14 10:47:54','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('52','Grade 1 to Grade 4','<p><b>Lemon Juice Making Activity</b> </p><p>Dear Parents,</p><p>On <b>Thursday, 16th October 2025</b> , we are conducting a Lemon Juice Making Activity.</p><p><b>Students should bring:</b> </p><p>½ lemon</p><p>1 steel glass</p><p>1 steel spoon</p><p>(Plastic glass and spoon are not allowed.)</p><p> Please write your child’s name on the glass and spoon. </p><p>Thank you!</p><p><br></p><p><b>Learn this poem for activity </b></p><p><b>Lemon Juice Poem  </b></p><p>Squeeze lemon… nice and sweet,</p><p>Add some sugar — what a treat!</p><p>Add some salt, just a bit,</p><p>Add some water — mix it, mix it!</p><p>Stir it well, take a sip,</p><p>Yummy juice for every lip!</p><p>Healthy drink, fresh and bright,</p><p>Lemon juice makes us feel right! </p>','3','2025-10-14','2025-10-14 10:53:53','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('53','Grade 1 to Grade 9','<p> Dear Parents,</p><p><br></p><p>We are delighted to announce that our <b>School Exhibition</b> for the <b>Academic Year 2025–26</b></p><p> is scheduled on <b>14th November 2025 (Friday)</b>.</p><p>Subject teachers have selected students for different subjects and allotted projects accordingly.</p><p>If you have any doubts regarding the Topic, Subject or Project; please feel free to contact the respective Subject Teacher or Class Teacher.</p><p>Your support and cooperation will surely make this exhibition a grand success!</p><p><br></p><p>Thank You!</p><p>Principal </p><p>PPGMIS</p>','3','2025-10-30','2025-10-30 08:22:08','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('54','Nursery to Grade 9','<p>Dear Parents,</p><p><br></p><p>The school will remain closed on<b> 5/11/25</b> on account of \"Guru Nanak Jayanti\".</p><p><br></p><p>Regards </p><p>PPGMIS</p>','3','2025-11-05','2025-11-04 14:32:31','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('55','Grade 1 to Grade 9','<p>Dear Parents,</p><p>Please note that the scheduled <b>Class Test for this month has been cancelled.</b></p><p>Students are advised to focus on the preparation for the upcoming Periodic Test – 2.</p><p><br></p><p>Thank you! </p><p>Principal </p><p>PPGMIS</p>','3','2025-11-06','2025-11-06 08:13:48','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('56','Nursery to Grade 8','<p>Dear Parents,</p><p>We are delighted to invite you to our grand exhibition — ✨Intellect Sphere 2025 ✨, a vibrant celebration of Science, Mathematics, Languages, Music, Art, Craft , Sports, Computers, Yoga, Skill Development, and Robotics.</p><p>Our young innovators are all set to amaze you with their creativity, curiosity, and talent through interactive exhibits and live demonstrations! ????</p><p><b>-Date: 14th November 2025</b></p><p><b>-Time: 10:00 a.m. – 12:00 noon</b></p><p><b>- Venue: P. P. Gagangiri Maharaj International School</b></p><p><br></p><p>Your gracious presence and encouragement will truly motivate our budding scientists, artists, technologists, and visionaries of tomorrow. </p><p><br></p><p>⸻</p><p><b>-Important Update – 13th November 2025</b></p><p><b>-There will be no school from Nursery to Grade 8.</b></p><p><b>-Students participating in the exhibition (all grades) are requested to report between 10:00 a.m. to 11:30 a.m. along with their models and materials.</b></p><p><br></p><p>We deeply appreciate your continued support and cooperation. </p><p><br></p><p>Warm regards,</p><p>Principal</p><p><br></p>','3','2025-11-12','2025-11-12 20:16:10','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('57','Nursery to Grade 9','<p>Greetings!</p><p><b>Tomorrow, 27/11/2025 (Thursday)</b>, there will be a holiday for Nursery to Grade 9 as our teachers will be attending a training session.</p><p><br></p><p><b>On Friday, 28/11/2025, regular school will be conducted and attendance is compulsory for all students.</b></p><p><br></p><p><b>From Saturday, 29/11/2025 our Annual Sports Meet will begin. </b>Further<b> </b>details  will be shared soon.</p><p><br></p><p><br></p><p>Thank you!</p><p>Principal </p><p>PPGMIS.</p>','3','2025-11-26','2025-11-26 18:33:45','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('58','Nursery to Grade 9','<p>Dear Parents,</p><p><br></p><p>School will remain <b>closed on 2nd December 2025</b> due to the Nagar Parishad Election.</p><p>Classes will resume on <b>3rd December 2025.</b></p><p><br></p><p>Regards, </p><p>Principal</p><p>PPGMIS</p>','3','2025-12-01','2025-12-01 21:23:47','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('59','Nursery to Prep2','<p>Dear Parents,</p><p>Please note the following important information for <b>Tomorrow – Friday, 05/12/2025</b>:</p><p>- KTSP Mandal’s Annual Sports Day Inauguration will be conducted tomorrow.</p><p>-Therefore, school will remain <b>CLOSED for students from Nursery to Prep2.</b></p><p><br></p><p>Thank you </p><p>Principal </p><p>PPGMIS</p>','3','2025-12-04','2025-12-04 19:15:37','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('60','Grade 1 to Grade 9','<p>Dear Parents,</p><p>Please note the following important information for <b>Tomorrow – Friday, 05/12/2025:</b></p><p>-KTSP Mandal’s Annual Sports Day Inauguration will be conducted tomorrow.</p><p>-Therefore, <b>school will remain CLOSED for students.</b></p><p><br></p><p>✅ <b>Periodic Test–2 Open Day will be conducted:</b></p><p><b>Timing: 10:00 AM to 11:00 AM</b></p><p><b>Parents are requested to strictly follow the given timing.</b></p><p><b></p><p><b>✅  Fees will NOT be accepted tomorrow (on Open Day).</b></p><p><br></p><p>Thank you </p><p>Principal </p><p>PPGMIS</p>','3','2025-12-04','2025-12-04 19:17:29','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('61','Grade 1 to Grade 9','<p>Dear Parents,</p><p>We are announcing the Winter Break schedule in advance so that you can plan accordingly.</p><p><br></p><p>-Winter Break</p><p><b>Tuesday, 23/12/2025 to Thursday, 01/01/2026</b></p><p><br></p><p>Important Notes</p><p><b>All students must report to school on Friday, 02/01/2026 (compulsory)</b></p><p><b>Saturday, 03/01/2026 will be a working day for Grades 1 to 9.</b></p><p><br></p><p>Thank you for your cooperation.</p><p><br></p><p>Regards,</p><p>Principal </p><p>PPGMIS</p>','3','2025-12-18','2025-12-18 12:12:12','1','1',NULL,NULL);
