INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('64','Grade 1 to Grade 9','Class Test.','3','2026-01-09','2026-01-02 10:05:14','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('65','Grade 1 to Grade 9','<p> Dear Parents,</p><p><br></p><p>This is to inform you that <b>tomorrow 3rd January, 2026</b>  will be a regular school day for Grades 1 to 9.</p><p><br></p><p><b>-School Timing: 7:40 a.m. to 12:00 noon</b></p><p><br></p><p>-Academic Schedule:</p><p><span xss=removed>Grades 1 to 5 will follow the Thursday timetable (first five periods).</span></p><p><br></p><p>Thank you for your continued cooperation.</p><p><br></p><p>Warm regards,</p><p>Principal</p><p>PPGMIS</p>','3','2026-01-02','2026-01-02 12:21:31','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('67','Nursery to Grade 9','<p>Dear Parents,</p><p>We are excited to announce that our school will be participating in <b>\"The Dream\"</b> National Level Art Competition. This is a golden opportunity for our young artists from <b>Nursery to Grade 9 </b>to showcase their talent and win national recognition!</p><p>-Competition Categories</p><p>Choose your favorite or participate in all!</p><p>1)Colouring Competition </p><p>2)Handwriting Competition </p><p>3)Cartoon Making </p><p>4)Drawing & Colouring </p><p>5)Craft Making (Waste to Best) </p><p>6) Collage Making</p><p> </p><p>- Important Details</p><p><b>Entry Fee : ₹60 per competition. </b></p><p><b>How to Enter: Please submit the entry fees to your respective Class Teacher.</b></p><p><b>Deadline for Fees: Monday, 12th January 2026.</b></p><p>Convenience: Competition papers will be provided for students to take home, allowing them to work in their comfort zone!</p><p><br></p><p>Regards, </p><p>PPGMIS</p>','3','2026-01-06','2026-01-06 10:55:13','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('68','Grade 3 to Grade 9','<p>Dear Parents,</p><p>We are delighted to inform you that the school is organizing a <b>one-day picnic to Saguna Baug, Neral</b> <b>on Friday, 16th January 2026.</b></p><p><b></p><p><b>-Picnic Charges: ₹1250 per student</b></p><p>The package includes:</p><p>* Insurance coverage  </p><p>* Day trip entry to Saguna Baug  </p><p>* Breakfast  </p><p>* Lunch  </p><p>* Evening snacks  </p><p>* AC bus transportation (School to Saguna Baug and return)  </p><p>* Picnic cap </p><p><br></p><p><b>-Payment Instructions</b></p><p>Interested students are requested to pay the exact amount in cash to their class teacher <b>on or before Saturday, 10th January 2026.</b></p><p><br></p><p>This trip will provide students with a refreshing learning experience in a natural environment while ensuring complete safety and comfort.</p><p><br></p><p>Warm regards,  </p><p>PPGMIS</p>','3','2026-01-08','2026-01-08 10:39:49','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('69','Nursery to Grade 2','<p>Dear Parents,</p><p>We are delighted to inform you that the school is organizing a one-day picnic  to Monteria Village, Kalote on <b>Tuesday, 27th January 2026</b>.</p><p><b>Picnic Charges: ₹1200 per student</b></p><p><br></p><p>-The package includes:</p><p>✅ Insurance coverage </p><p>✅ Day trip entry to Monteria Village </p><p>✅ Breakfast </p><p>✅ Lunch </p><p>✅ Evening snacks </p><p>✅ Bus transportation (School to Monteria Village & return) </p><p><br></p><p>-Payment Instructions:</p><p>Interested students are requested to pay the exact amount in cash to their class teacher<b> on or before Thursday, 22nd January 2026</b>.</p><p>This trip will provide students with a refreshing learning experience in a natural environment while ensuring complete safety and comfort.</p><p><br></p><p>Warm regards,</p><p>PPGMIS </p>','3','2026-01-20','2026-01-20 08:47:52','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('70','Nursery to Grade 9','<p>Dear Parents, </p><p><br></p><p>In view of the unfortunate demise of the Hon’ble Deputy Chief Minister Mr. Ajit Dada Pawar, the school management has decided to disperse students early today.</p><p><br></p><p>Parents are requested to please come and collect their wards from school at around <b>11:30 a.m.</b></p><p><br></p><p>Kindly also inform the auto drivers accordingly.</p><p><br></p><p>Thank you for your cooperation.</p><p><br></p><p>Regards,  </p><p>PPGMIS</p>','3','2026-01-28','2026-01-28 11:24:38','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('71','Grade 1 to Grade 9','<p>Dear Parents,</p><p><br></p><p>This is to inform you that due to the HSC Examinations, the school schedule will be as follows:</p><p><br></p><p><b>* 10th February 2026 (Tuesday): Non-Instructional Day (Holiday)  </b></p><p><b>* 11th & 12th February 2026 (Wednesday & Thursday): Half Day  </b></p><p><br></p><p><b>School Timing on Half Days:  </b></p><p><b>7:40 a.m. to 10:00 a.m.  </b></p><p><br></p><p>Parents are requested to ensure that their ward reaches school sharp at 7:30 a.m.</p><p><br></p><p>The special timetable for Wednesday and Thursday will be shared shortly.</p><p><br></p><p>Thank you for your cooperation.</p><p><br></p><p>Regards,  </p><p>PPGMIS, Khopoli</p>','3','2026-02-09','2026-02-09 11:51:01','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('72','Nursery to Prep 2','<p>Dear Parents,</p><p><br></p><p>Due to the<b> HSC examination tomorrow, 10 February 2026, </b>it will be a non-instructional day <b>(holiday) for the Pre-Primary section.</b></p><p><br></p><p>From <b>Thursday onwards, regular school timings will be followed</b></p><p><b>Nursery-9:30 a.m. to 12:30 p.m.</b></p><p><b>Prep 1 & Prep 2-9:00 a.m. to 1:00 p.m.</b></p><p><br></p><p>Thank you</p><p>PPGMIS</p>','3','2026-02-09','2026-02-09 14:32:25','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('73','Grade 1 to Grade 3','<p>Dear Parents,</p><p><br></p><p>We are happy to inform you that the Annual Examinations for Grades 1 to 3 have been successfully completed. </p><p><br></p><p>Further information regarding the result declaration and book distribution will be shared with you shortly. Kindly stay updated for the upcoming notice.</p><p><br></p><p>Thank you for your continued support.</p><p><br></p><p>Regards,</p><p>PPGMIS</p>','3','2026-03-05','2026-03-05 16:52:55','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('74','Nursery To Prep 2','<p>Dear Parents,</p><p><br></p><p>We are happy to inform you that the Annual Examinations for preprimary has been successfully completed. </p><p><br></p><p>Further information regarding the result declaration and book distribution will be shared with you shortly. Kindly stay updated for the upcoming notice.</p><p><br></p><p>Thank you for your continued support.</p><p><br></p><p>Regards,</p><p>PPGMIS</p>','3','2026-03-07','2026-03-07 08:06:16','1','1',NULL,NULL);
INSERT INTO `notice` (`noticeID`,`title`,`notice`,`schoolyearID`,`date`,`create_date`,`create_userID`,`create_usertypeID`,`classesID`,`sectionID`) VALUES ('75','Prep 2','<p>Invitation for Senior KG Parents </p><p><br></p><p>Dear Parents,</p><p>We are delighted to invite you to attend the Senior KG (Pre-Primary) Programme at our school.</p><p>Your presence will encourage and motivate our little graduates as they step into a new journey of learning.</p><p><b> Date: 09th March, 2026</b></p><p><b> Time: 10am</b></p><p><b>Venue: Great Hall</b></p><p>Kindly be present and make this day special for your child.</p><p><br></p><p>Looking forward to your gracious presence.</p><p><br></p><p>Thank you.</p><p>Regards,</p><p>PPGMIS</p>','3','2026-03-07','2026-03-07 12:39:13','1','1',NULL,NULL);
